// Pure content: no Three/startup side effects. Order follows the English primary.
export const COMPLETION_SOURCES={
 motor:'https://help.prusa3d.com/article/clogged-nozzle-core-one-core-one-l-xl-mk4-s-mk3-9-s_411823#how-to-fix-the-clogged-printer',
 heat:'https://help.prusa3d.com/article/clogged-nozzle-core-one-core-one-l-xl-mk4-s-mk3-9-s_411823#procedures-that-require-nozzle-heating',
 manual:'https://help.prusa3d.com/article/cold-pull-31702-core-one-35702-core-one-l_930551#manual-cold-pull',
 results:'https://help.prusa3d.com/article/cold-pull-31702-core-one-35702-core-one-l_930551#results',
 align:'https://help.prusa3d.com/article/gearbox-alignment-core-one-l-core-one-xl-mk4-s-mk3-9-s_465779'
};
const l=s=>s.split('|'),clone=x=>structuredClone(x);
const make=(id,title,body,refs,source,extra={})=>({id,title:l(title),body:l(body),refs,source,inspection:true,headOnly:!refs.includes('lcd'),camera:refs.includes('lcd')?'front':'hotend-perspective',...extra});
const TUBE=['regionTube','regionHeatbreak','regionTip'];
export function makeCompletionTasks(base){
 const sensor=base.find(t=>t.id==='sensor-service');if(!sensor)throw Error('Missing original sensor-service');
 const get=id=>{const s=sensor.steps.find(s=>s.id===id);if(!s)throw Error('Missing original PG step '+id);return clone(s);};
 const needle={id:'needle-clear',revision:1,category:1,needleClear:true,title:l('非HFのみ：清掃針で詰まりを除く|Non-HF only: clear with a cleaning needle|Pouze bez HF: čištění jehlou|Nur Nicht-HF: mit Reinigungsnadel reinigen'),interval:l('非HFを確認できたとき|Only after confirming non-HF|Pouze po ověření trysky bez HF|Nur bei bestätigter Nicht-HF-Düse'),source:COMPLETION_SOURCES.heat,steps:[
  make('needle-scope','非HFであることを確認する|Confirm a non-HF nozzle|Ověřit trysku bez HF|Nicht-HF-Düse bestätigen','装着品が非HFのPrusa Nozzleであることを確認します。HFノズルや種類不明のノズルには針を入れません。上流の破片や供給側の詰まりは先に該当手順で確認します。|Confirm that the installed Prusa Nozzle is non-HF. Do not insert a needle into an HF nozzle or an unidentified nozzle. Check upstream fragments and supply restrictions using their own procedures first.|Ověřte, že osazená Prusa Nozzle není HF. Do HF trysky ani do trysky neznámého typu jehlu nezavádějte. Nejprve příslušnými postupy zkontrolujte úlomky výše v dráze a odpor přívodu.|Prüfen, ob die eingebaute Prusa Nozzle keine HF-Düse ist. Keine Nadel in HF-Düsen oder unbekannte Düsentypen einführen. Bruchstücke weiter oben und Zufuhrwiderstände zuerst mit den passenden Verfahren prüfen.',['regionTip'],COMPLETION_SOURCES.heat,{related:['clog','feed-clear','fragment']}),
  make('needle-heat','実機で材料に合う温度へ加熱する|Heat on the printer for the material|Zahřát na tiskárně podle materiálu|Am Drucker passend zum Material heizen','プリンターの温度メニューで、使用するフィラメントに適したノズル温度を設定します。実機の到達表示を確認します。外部の熱源は使わず、熱いホットエンドには触れません。|Use the printer temperature menu to set the nozzle temperature suitable for the filament material. Check the reached temperature on the printer. Use no external heat source and do not touch the hot hotend.|V teplotní nabídce tiskárny nastavte teplotu trysky vhodnou pro materiál filamentu. Dosažení teploty ověřte na tiskárně. Nepoužívejte vnější zdroj tepla a nedotýkejte se horkého hotendu.|Im Temperaturmenü des Druckers eine zum Filamentmaterial passende Düsentemperatur einstellen. Das Erreichen am Drucker prüfen. Keine externe Wärmequelle verwenden und das heiße Hotend nicht berühren.',TUBE,COMPLETION_SOURCES.heat,{firmwareActions:['heat']}),
  make('needle-feed','針より先にフィラメントを入れる|Introduce filament before the needle|Nejprve zavést filament|Filament vor der Nadel einführen','フィラメントを先に入れます。このあと、非HFノズルの下から針を使います。突然溶けた樹脂が出る場合に備えて保護手袋を使います。|Introduce filament first. The next step uses the needle from below the non-HF nozzle. Wear protective gloves against a sudden release of molten material.|Nejprve zaveďte filament. V dalším kroku použijete jehlu zespodu trysky bez HF. Pro případ náhlého výtoku taveniny použijte ochranné rukavice.|Zuerst Filament einführen. Im nächsten Schritt wird die Nadel von unten an der Nicht-HF-Düse verwendet. Zum Schutz vor plötzlich austretender Schmelze Schutzhandschuhe tragen.',['regionTube','regionTip'],COMPLETION_SOURCES.heat),
  make('needle-in','針を下から約1–2cm入れる|Insert the needle about 1–2 cm from below|Zasunout jehlu zespodu asi 1–2 cm|Nadel von unten etwa 1–2 cm einführen','非HFのみの手順です。HFや種類不明には使いません。付属の清掃針、または0.3–0.35mmの細いワイヤーをノズルの下から約1–2cm入れます。高温部に触れません。入らない・強い抵抗がある・種類が確認できない場合は、無理に押さずこの方法を中止します。|Non-HF only: do not use on HF or unknown nozzles. Insert the supplied cleaning needle or a thin 0.3–0.35 mm wire approximately 1–2 cm into the nozzle from below. Avoid hot parts. If it will not enter, meets strong resistance or the type is not confirmed, stop this method rather than forcing it.|Pouze bez HF: nepoužívejte pro HF ani neznámé trysky. Dodanou čisticí jehlu nebo tenký drát 0,3–0,35 mm zasuňte zespodu do trysky asi 1–2 cm. Nedotýkejte se horkých částí. Pokud nejde zasunout, klade silný odpor nebo typ není ověřen, nepoužívejte sílu a tento postup ukončete.|Nur Nicht-HF: nicht bei HF-Düsen oder unbekanntem Typ verwenden. Mitgelieferte Reinigungsnadel oder dünnen Draht mit 0,3–0,35 mm von unten etwa 1–2 cm in die Düse einführen. Heiße Teile meiden. Lässt sie sich nicht einführen, besteht starker Widerstand oder ist der Typ unklar, Verfahren ohne Gewalt abbrechen.',['regionTip'],COMPLETION_SOURCES.heat),
  make('needle-check','ロードして吐出を確かめる|Load and check extrusion|Zavést filament a ověřit extruzi|Laden und Extrusion prüfen','針を抜き、実機LCDのLoad Filamentを選んで、ノズルから樹脂が出るか確認します。必要なら、針を入れる段階とこのロード確認を繰り返します。|Withdraw the needle, choose Load Filament on the printer LCD and check material emerging from the nozzle. If needed, repeat the needle step and this loading check.|Vytáhněte jehlu, na LCD tiskárny zvolte Load Filament a ověřte výstup materiálu. Podle potřeby opakujte krok s jehlou a tuto kontrolu zavádění.|Nadel herausziehen, am Drucker-LCD Load Filament wählen und den Materialaustritt prüfen. Bei Bedarf Nadelschritt und diese Ladeprüfung wiederholen.',['regionTip','lcd'],COMPLETION_SOURCES.heat,{firmwareActions:['load']}),
  make('needle-result','復旧・中止・次の方法を選ぶ|Choose recovery or the next method|Vyhodnotit výsledek nebo zvolit další postup|Ergebnis oder nächstes Verfahren wählen','正常に吐出すれば清掃は完了です。流れが戻らなければ、新しいフィラメントによる詰まり除去を確認します。一部でも吐出する対応ノズルならコールドプルも選べます。交換する場合は完全に冷却し、電源を切って抜栓してから交換手順へ進みます。|Normal extrusion completes cleaning. If flow does not return, review clearing with fresh filament. A compatible nozzle that still extrudes some material can also use cold pull. Before replacement, cool fully, switch off and unplug, then follow the replacement procedure.|Při normální extruzi je čištění hotové. Neobnoví-li se tok, projděte protlačení nového filamentu. U vhodné trysky s alespoň částečným tokem lze zvolit cold pull. Před výměnou nechte vše vychladnout, vypněte a odpojte napájení a pokračujte návodem k výměně.|Bei normaler Extrusion ist die Reinigung abgeschlossen. Ohne wiederhergestellten Fluss das Verfahren mit frischem Filament prüfen. Bei geeigneter Düse mit Teilfluss ist auch Cold Pull möglich. Vor Austausch vollständig abkühlen lassen, ausschalten, Netzstecker ziehen und dann dem Austauschverfahren folgen.',TUBE,COMPLETION_SOURCES.heat,{related:['feed-clear','coldpull','coldpull-manual','nozzle']})
 ]};
 const manual={id:'coldpull-manual',revision:1,category:1,manualColdPull:true,title:l('コールドプル（手動）|Manual cold pull|Ruční cold pull|Manueller Cold Pull'),interval:l('部分詰まり・手動で行う場合|Partial blockage; manual method|Částečné ucpání; ruční postup|Teilweise Verstopfung; manuelles Verfahren'),source:COMPLETION_SOURCES.manual,steps:[
  make('manual-scope','適合とPLAを確認する|Check compatibility and prepare PLA|Ověřit vhodnost a připravit PLA|Eignung prüfen und PLA vorbereiten','一部でも樹脂が出るノズルが対象です。完全詰まりやNozzle Xには使いません。PLAとペンチを用意します。自動Cold Pullとは温度・抜く時機が異なります。上部へ触れる前に高温部を冷まし、ベッドを下げて停止を確認します。|Use only when some material still exits; not for a complete blockage or Nozzle X. Prepare PLA and pliers. Temperatures and pull timing differ from automatic Cold Pull. Before reaching the top, let hot parts cool, lower the bed and wait for it to stop.|Použijte jen při alespoň částečném toku; ne při úplném ucpání ani s Nozzle X. Připravte PLA a kleště. Teploty a okamžik tahu se liší od automatického Cold Pullu. Před přístupem shora nechte horké díly vychladnout, spusťte podložku níže a vyčkejte zastavení.|Nur bei noch vorhandenem Teilfluss verwenden, nicht bei vollständiger Verstopfung oder Nozzle X. PLA und Zange bereitlegen. Temperaturen und Zugzeitpunkt unterscheiden sich vom automatischen Cold Pull. Vor Zugriff oben heiße Teile abkühlen lassen, Bett absenken und Stillstand abwarten.',TUBE,COMPLETION_SOURCES.manual,{firmwareActions:['moveZ'],related:['clog','coldpull']}),
  make('manual-inlet','ガイドを上げて金属継手を外す|Lift the guide and unscrew the fitting|Zvednout vodítko a vyšroubovat šroubení|Führung anheben und Fitting abschrauben','装着されているBowden bendを押し上げ、金属継手をねじって外し、Nextruder上部から直接フィラメントを入れられる状態にします。配線を引いて空間を作りません。|Push up the fitted Bowden bend and unscrew the metal fitting to feed directly into the top of the Nextruder. Do not pull wiring aside to gain access.|Osazený Bowden bend posuňte nahoru a vyšroubujte kovové šroubení, abyste mohli filament zavádět přímo shora do Nextruderu. Za kabeláž kvůli přístupu netahejte.|Montierten Bowden bend hochschieben und Metallfitting abschrauben, um Filament direkt oben in den Nextruder einzuführen. Für den Zugang nicht an Leitungen ziehen.',['bowdenBend',817,'ptfeTube'],COMPLETION_SOURCES.manual),
  make('manual-sensor-off','フィラメント検知を一時的にOFFにする|Temporarily turn filament sensing off|Dočasně vypnout detekci filamentu|Filamenterkennung vorübergehend ausschalten','元の設定を覚えておき、実機のSettings → Filament Sensingでフィラメント検知をOFFにします。上から直接PLAを入れるための設定です。|Note the original setting and turn filament sensing off in Settings → Filament Sensing on the printer. This allows direct PLA feeding from above.|Zapamatujte si původní nastavení a na tiskárně v Settings → Filament Sensing vypněte detekci filamentu. Jde o nastavení pro přímé zavádění PLA shora.|Ursprüngliche Einstellung merken und am Drucker unter Settings → Filament Sensing die Erkennung ausschalten. Dies dient der direkten PLA-Zufuhr von oben.',['lcd'],COMPLETION_SOURCES.manual),
  make('manual-load','上からPLAをロードする|Load PLA from above|Zavést PLA shora|PLA von oben laden','実機のFilament → Load Filament → PLAを選び、Nextruder上部からPLAをロードします。この段階はまだアイドラーを閉じた状態です。|Choose Filament → Load Filament → PLA on the printer and load PLA through the top of the Nextruder. Keep the idler closed for this loading step.|Na tiskárně zvolte Filament → Load Filament → PLA a zaveďte PLA shora do Nextruderu. Pro tento krok ponechte idler zavřený.|Am Drucker Filament → Load Filament → PLA wählen und PLA von oben in den Nextruder laden. Für diesen Ladeschritt den Idler geschlossen halten.',['regionTube','lcd'],COMPLETION_SOURCES.manual,{firmwareActions:['load']}),
  make('manual-idler-open','スイベルを開放する|Release the idler swivel|Otevřít otočný díl idleru|Idler-Schwenkhebel öffnen','PLAを入れたらIdler Swivelを開放します。続く手順ではフィラメントを手で押し、最後に真上へ引き抜きます。|After loading PLA, open the Idler Swivel. The next steps push filament by hand and finally pull it straight upward.|Po zavedení PLA otevřete otočný díl idleru. V dalších krocích budete filament tlačit ručně a nakonec jej vytáhnete přímo vzhůru.|Nach dem Laden von PLA den Idler-Schwenkhebel öffnen. Danach wird Filament von Hand geschoben und am Ende gerade nach oben gezogen.',['pgAssembly','idlerBearing1','idlerBearing2',798],COMPLETION_SOURCES.manual),
  make('manual-fill','270°CにしてPLAで満たす|Heat to 270 °C and fill with PLA|Zahřát na 270 °C a naplnit PLA|Auf 270 °C heizen und mit PLA füllen','実機のControl → Temperature → Nozzle Temperatureで270°Cにします。到達したらPLAを手で押し、ノズルから出るまで充填します。熱い部品には触れません。|Set 270 °C in Control → Temperature → Nozzle Temperature on the printer. Once reached, push PLA by hand until it flows from the nozzle. Do not touch hot parts.|Na tiskárně v Control → Temperature → Nozzle Temperature nastavte 270 °C. Po dosažení teploty ručně tlačte PLA, dokud nevytéká z trysky. Nedotýkejte se horkých částí.|Am Drucker unter Control → Temperature → Nozzle Temperature 270 °C einstellen. Nach Erreichen PLA von Hand drücken, bis es aus der Düse fließt. Heiße Teile nicht berühren.',TUBE,COMPLETION_SOURCES.manual,{firmwareActions:['heat']}),
  make('manual-cool-fill','冷却を始め、流れなくなるまで押す|Start cooling and keep the nozzle filled|Spustit chlazení a udržet trysku naplněnou|Abkühlen beginnen und Düse gefüllt halten','Control → Temperature → Cooldownで加熱を止めます。PLAが溶けて出なくなる温度（約170°C）まで手で押し続け、ノズルを満たします。必要ならペンチで慎重に押します。|Stop heating with Control → Temperature → Cooldown. Continue pushing by hand until PLA no longer melts and exits, at about 170 °C, keeping the nozzle filled. Pliers can help push carefully.|Vypněte ohřev pomocí Control → Temperature → Cooldown. Dále ručně tlačte, dokud PLA nepřestane tát a vytékat, přibližně při 170 °C, aby tryska zůstala naplněná. Opatrnému tlačení mohou pomoci kleště.|Heizen über Control → Temperature → Cooldown stoppen. Von Hand weiterdrücken, bis PLA bei etwa 170 °C nicht mehr schmilzt und austritt, damit die Düse gefüllt bleibt. Eine Zange kann beim vorsichtigen Drücken helfen.',TUBE,COMPLETION_SOURCES.manual,{firmwareActions:['cooldown']}),
  make('manual-wait','下の樹脂を除き、100°Cを待つ|Clear below and wait for 100 °C|Odstranit materiál pod tryskou a čekat na 100 °C|Material darunter entfernen und 100 °C abwarten','ノズル下に出た樹脂を取り除き、引き抜きを妨げないようにします。高温部に触れず、実機の温度が100°Cになるのを待ちます。|Remove extruded material below the nozzle so it cannot obstruct the pull. Avoid hot parts and wait until the actual printer temperature reaches 100 °C.|Odstraňte vytlačený materiál pod tryskou, aby nebránil vytažení. Nedotýkejte se horkých částí a čekejte, až skutečná teplota na tiskárně dosáhne 100 °C.|Ausgetretenes Material unter der Düse entfernen, damit es den Zug nicht behindert. Heiße Teile meiden und warten, bis die tatsächliche Druckertemperatur 100 °C erreicht.',['regionTip'],COMPLETION_SOURCES.manual),
  make('manual-pull','100°Cで真上へ一定に引く|At 100 °C pull steadily straight up|Při 100 °C táhnout rovnoměrně vzhůru|Bei 100 °C gleichmäßig gerade nach oben ziehen','100°Cに達したらペンチでフィラメントをつかみ、もう片方の手でNextruderを支え、ゆっくり一定に真上へ引きます。横へ曲げず、完全に抜けるまで続けます。強い抵抗で抜けない場合は無理をせず中止し、詰まり対処へ戻ります。|At 100 °C grip the filament with pliers, support the Nextruder with your other hand and pull slowly and steadily straight upward. Do not bend it sideways; continue until fully removed. If strong resistance prevents removal, do not force it; stop and return to blockage checks.|Při 100 °C uchopte filament kleštěmi, druhou rukou podepřete Nextruder a pomalu, rovnoměrně táhněte přímo vzhůru. Neohýbejte jej do strany a pokračujte do úplného vytažení. Při silném odporu nepoužívejte sílu; přerušte postup a vraťte se ke kontrole ucpání.|Bei 100 °C Filament mit Zange greifen, Nextruder mit der anderen Hand stützen und langsam, gleichmäßig gerade nach oben ziehen. Nicht seitlich biegen; bis zum vollständigen Herausziehen fortfahren. Bei starkem Widerstand keine Gewalt anwenden, abbrechen und Verstopfung prüfen.',TUBE,COMPLETION_SOURCES.manual,{related:['clog','feed-clear']}),
  make('manual-idler-close','アイドラーとスイベルを閉じる|Close the idler and swivel|Zavřít idler a otočný díl|Idler und Schwenkhebel schließen','フィラメントを取り除いたら、アイドラーを閉じてスイベルでロックします。|After removing the filament, close the idler and lock the swivel.|Po vytažení filamentu zavřete idler a zajistěte otočný díl.|Nach Entfernen des Filaments Idler schließen und Schwenkhebel verriegeln.',['idlerBearing1','idlerBearing2',798],COMPLETION_SOURCES.manual),
  make('manual-inlet-refit','継手を戻し、ガイドを下げる|Refit the fitting and lower the guide|Vrátit šroubení a spustit vodítko|Fitting montieren und Führung absenken','外した金属継手をねじ戻し、Bowden bendを元の位置まで押し下げます。配管と配線を挟んでいないことを確認します。|Screw the removed metal fitting back in and push the Bowden bend down to its original position. Check that tubing and wires are not trapped.|Vyšroubované kovové šroubení vraťte a Bowden bend zatlačte do původní polohy. Zkontrolujte, že trubičky ani kabely nejsou skřípnuté.|Entferntes Metallfitting wieder einschrauben und Bowden bend in die ursprüngliche Position herunterdrücken. Auf eingeklemmte Schläuche und Leitungen prüfen.',['bowdenBend',817,'ptfeTube'],COMPLETION_SOURCES.manual),
  make('manual-result','先端を確認し、設定を戻す|Inspect the tip and restore settings|Zkontrolovat špičku a obnovit nastavení|Spitze prüfen und Einstellung zurücksetzen','抜いた先端に古い樹脂や焦げがないか見ます。汚れが残れば同じ手順を繰り返します。終了時は一時的に変えたフィラメント検知を元の設定へ戻し（元がONならON）、ロードと吐出を確認します。改善しなければ詰まり対処またはノズル交換へ進みます。|Inspect the pulled tip for old material or burnt residue. Repeat the procedure if dirty. At completion restore the original filament-sensing setting (ON if it was ON), then check loading and extrusion. If unresolved, return to blockage checks or nozzle replacement.|Na vytažené špičce hledejte starý materiál nebo připálené zbytky. Je-li špinavá, postup opakujte. Nakonec vraťte původní nastavení detekce filamentu (zapnuto, pokud bylo zapnuto) a ověřte zavádění i extruzi. Bez zlepšení zkontrolujte ucpání nebo vyměňte trysku.|Gezogene Spitze auf altes Material oder verbrannte Reste prüfen. Bei Verschmutzung Verfahren wiederholen. Zum Abschluss ursprüngliche Filamenterkennung wiederherstellen (EIN, wenn zuvor EIN) und Laden sowie Extrusion prüfen. Ohne Verbesserung Verstopfung prüfen oder Düse austauschen.',TUBE,COMPLETION_SOURCES.results,{related:['clog','nozzle']})
 ]};
 const ids=['unload-cool','power-off','cover-out','idler-open','case-screws-out','block-out','block-in','case-screws-in','idler-close','cover-in','power-on','align-start','align-open','align-wait','align-tighten','align-close'];
 const motor={id:'motor-check',revision:1,category:1,motorInspection:true,title:l('Nextruderモーター軸を点検する|Check the Nextruder motor shaft|Kontrola hřídele motoru Nextruderu|Nextruder-Motorwelle prüfen'),interval:l('簡易清掃後も送り不良が残るとき|If feeding trouble remains after simple cleaning|Přetrvává-li potíž po jednoduchém čištění|Bei verbleibenden Förderproblemen nach einfacher Reinigung'),source:COMPLETION_SOURCES.motor,steps:[
  make('scope','PG一体取外しの準備を確認する|Prepare for unit removal|Připravit vyjmutí celku PG|Ausbau der PG-Einheit vorbereiten','簡易清掃後も送りに問題がある場合の点検です。PG-assembly-adapterと2.5mm六角レンチを先に用意します。以降は冷却・電源切断状態で、ケース・リング・ギア・main-plateを一体のまま扱います。固着した部品をこじって外しません。|This inspection is for feeding problems remaining after simple cleaning. Have the PG-assembly-adapter and 2.5 mm Allen key ready first. Work cold and powered off, retaining the case, ring, gearbox and main plate as one unit. Do not pry stuck parts free.|Kontrola je pro potíže s podáváním přetrvávající po jednoduchém čištění. Nejprve připravte PG-assembly-adapter a 2,5 mm imbus. Pracujte za studena a s vypnutým napájením; kryt, kroužek, převodovka a hlavní deska zůstávají jedním celkem. Zaseklé díly nepáčte.|Diese Prüfung gilt für Förderprobleme nach einfacher Reinigung. PG-assembly-adapter und 2,5-mm-Inbus zuerst bereitlegen. Kalt und ausgeschaltet arbeiten; Gehäuse, Ring, Getriebe und Hauptplatte als Einheit belassen. Festsitzende Teile nicht heraushebeln.',[816,'mainPlate','pgAssembly','pgRing'],COMPLETION_SOURCES.motor,{related:['extruder']}),
  ...ids.map(get)
 ]};
 // Preserve the tested access/alignment content; add only the actual missing check.
 for(const id of ['block-out','block-in']){
  const step=motor.steps.find(s=>s.id===id);step.source=COMPLETION_SOURCES.motor;step.related=['sensor-gearbox-recovery'];
  if(id==='block-out')step.body=l('ケース・リング・ギア・main-plateを崩さず一体のまま外し、安全に支えます。部品が分かれた場合は、先へ進めず下のPG復旧手順で組み直します。センサーホルダーを外す作業ではありません。|Remove and safely support the case, ring, gearbox and main plate as one unit. If they separate, pause here and use the PG recovery procedure below. This operation does not remove the sensor holder.|Vyjměte a bezpečně podepřete kryt, kroužek, převodovku a hlavní desku jako jeden celek. Pokud se rozdělí, zastavte a použijte níže postup obnovy PG. Nejde o vyjmutí držáku senzoru.|Gehäuse, Ring, Getriebe und Hauptplatte als Einheit abnehmen und sicher stützen. Trennen sie sich, hier anhalten und das unten verlinkte PG-Wiederherstellungsverfahren verwenden. Der Sensorhalter wird hierbei nicht entfernt.');
 }
 motor.steps.splice(motor.steps.findIndex(s=>s.id==='block-in'),0,make('motor-shaft','軸を手で回し、抵抗を確かめる|Turn the shaft by hand and feel resistance|Rukou otočit hřídelí a posoudit odpor|Welle von Hand drehen und Widerstand prüfen','冷却・電源切断を保ち、露出したモーター軸を指で回します。わずかで均一な抵抗を伴い、比較的滑らかに回るか確かめます。強い抵抗・引っ掛かり・ざらつきがあれば無理に回さず、復旧後も使用を再開せずサポートへ相談します。この点検だけで異物・歯の摩耗・モーター故障を断定しません。|Keep the printer cold and powered off. Turn the exposed motor shaft with your fingers and feel whether it rotates fairly smoothly with slight, uniform resistance. Do not force harsh resistance, catching or grinding; after reassembly seek support before resuming use. This check alone does not identify debris, worn gears or a motor fault.|Tiskárna zůstává studená a bez napájení. Prsty otáčejte odkrytou hřídelí a posuďte poměrně hladký chod s mírným, rovnoměrným odporem. Silný odpor, zadrhávání či drhnutí nepřemáhejte; po sestavení se před dalším použitím obraťte na podporu. Samotná kontrola nerozliší nečistoty, opotřebená kola a závadu motoru.|Drucker kalt und ausgeschaltet lassen. Freiliegende Motorwelle mit den Fingern drehen und auf relativ gleichmäßigen Lauf mit leichtem, gleichbleibendem Widerstand achten. Starken Widerstand, Haken oder Schleifen nicht mit Gewalt überwinden; nach Zusammenbau vor weiterer Nutzung Support kontaktieren. Die Prüfung allein unterscheidet Fremdkörper, verschlissene Räder und Motorfehler nicht.',[790,792],COMPLETION_SOURCES.motor));
 motor.steps.push(make('motor-result','位置合わせ後、送りを確認する|Check feeding after alignment|Po zarovnání ověřit podávání|Förderung nach Ausrichtung prüfen','ブロックとカバーを戻し、実機のPG位置合わせを最後まで終えたことを確認します。軸の異常がなかった場合にロードと吐出を試します。不調が残る場合は同じ分解を繰り返さずサポートへ相談します。|Check that the block and cover are refitted and the printer gearbox alignment is fully complete. If the shaft had no abnormal resistance, check loading and extrusion. If the problem persists, seek support rather than repeating disassembly.|Ověřte vrácení bloku a krytu a úplné dokončení zarovnání převodovky na tiskárně. Pokud hřídel neměla neobvyklý odpor, ověřte zavádění a extruzi. Při trvání potíží raději kontaktujte podporu než opakovat rozebírání.|Prüfen, ob Block und Abdeckung montiert sind und die Getriebeausrichtung am Drucker vollständig beendet ist. Ohne ungewöhnlichen Wellenwiderstand Laden und Extrusion prüfen. Bei verbleibendem Problem Support kontaktieren, statt erneut zu zerlegen.',['regionTube','regionTip'],COMPLETION_SOURCES.motor,{related:['clog']}));
 return [needle,manual,motor];
}
